local COURSE = HttpService:JSONDecode(COURSE_JSON)
assert(COURSE.version == 2, "this main.lua is the v2 world")
local NODES = {}
for _, n in ipairs(COURSE.nodes) do NODES[n.id] = n end
local W = COURSE.world
local B = COURSE.boundary
local LINE = COURSE.centreline

local GROUND_HEIGHT = 10
local GROUND_Y = -(GROUND_HEIGHT * 0.5)
local OCEAN_TOP_Y = -0.5
local PEN = NODES.N0.zone.c
local SPAWN = Vector3.new(PEN[1], 3, PEN[2])
local terrainPhysics = PhysicalProperties.new(2.0, 1.4, 0.0, 1.0, 1.0)

local function part(name, size, pos, color, opts)
    opts = opts or {}
    local p = Instance.new("Part")
    p.Name = name
    p.Size = size
    if opts.yaw then
        p.CFrame = CFrame.new(pos) * CFrame.Angles(0, math.rad(opts.yaw), 0)
    else
        p.Position = pos
    end
    p.Anchored = true
    p.CanCollide = opts.collide ~= false
    p.Color = color
    p.Material = opts.material or Enum.Material.SmoothPlastic
    if opts.transparency then p.Transparency = opts.transparency end
    if opts.role then p:SetAttribute("RenderRole", opts.role) end
    if opts.terrain then p.CustomPhysicalProperties = terrainPhysics end
    p:SetAttribute("CourseTag", opts.tag or "course")
    p.Parent = Workspace
    return p
end

