local function pad(name, c, r, color)
    return part(name, Vector3.new(r * 2, 0.1, r * 2), Vector3.new(c[1], 0.05, c[2]), color, { collide = false, tag = "pad" })
end
pad("Pad_N0_StartPen", PEN, NODES.N0.zone.r, Color3.fromRGB(255, 255, 255))
local rw = W.runway
part("Runway", Vector3.new(rw.width, 0.06, rw.z[2] - rw.z[1]), Vector3.new(rw.x, 0.03, (rw.z[1] + rw.z[2]) / 2), Color3.fromRGB(70, 70, 76), { collide = false, tag = "runway" })
for i, o in ipairs(W.runway_obstacles) do
    local s = o.size
    part("Runway_" .. o.kind .. "_" .. i, Vector3.new(s[1], s[2], s[3]), Vector3.new(o.c[1], s[2] / 2, o.c[2]),
