part("GustShore", Vector3.new(gb.max[1] - gb.min[1], 0.04, gb.max[2] - gb.min[2]), Vector3.new((gb.min[1] + gb.max[1]) / 2, 0.02, (gb.min[2] + gb.max[2]) / 2),
    Color3.fromRGB(80, 220, 255), { collide = false, transparency = 0.6, tag = "gust" })
local squallPart = part("Squall", Vector3.new(28, 0.05, 28), Vector3.new(PEN[1], 0.08, PEN[2]), Color3.fromRGB(255, 110, 200),
    { collide = false, transparency = 0.75, tag = "squall" })

--------------------------------------------------------------------------------
-- CENTRELINE (arc length, projection)
--------------------------------------------------------------------------------
local CUM = { 0 }
for i = 2, #LINE do
    CUM[i] = CUM[i - 1] + math.sqrt((LINE[i][1] - LINE[i - 1][1]) ^ 2 + (LINE[i][2] - LINE[i - 1][2]) ^ 2)
end
local L = CUM[#LINE]
local function pointAt(s)
    s = math.max(0, math.min(L, s))
    for i = 2, #LINE do
        if s <= CUM[i] then
            local f = (s - CUM[i - 1]) / math.max(1e-6, CUM[i] - CUM[i - 1])
            return LINE[i - 1][1] + (LINE[i][1] - LINE[i - 1][1]) * f, LINE[i - 1][2] + (LINE[i][2] - LINE[i - 1][2]) * f
        end
    end
    return LINE[#LINE][1], LINE[#LINE][2]
end
-- nearest arc position within [lo, hi]
local function project(x, z, lo, hi)
    local best, bs = math.huge, lo
    for i = 2, #LINE do
        if CUM[i] >= lo and CUM[i - 1] <= hi then
            local ax, az, bx, bz = LINE[i - 1][1], LINE[i - 1][2], LINE[i][1], LINE[i][2]
            local dx, dz = bx - ax, bz - az
            local l2 = math.max(1e-9, dx * dx + dz * dz)
            local f = math.max(0, math.min(1, ((x - ax) * dx + (z - az) * dz) / l2))
            local s = CUM[i - 1] + f * math.sqrt(l2)
            if s >= lo and s <= hi then
                local d = (x - ax - f * dx) ^ 2 + (z - az - f * dz) ^ 2
                if d < best then best, bs = d, s end
            end
        end
    end
    return bs
end
local NODE_S = {}
local ORDER = { "N1", "N2", "N3", "N4", "N5", "N6" }
for _, id in ipairs(ORDER) do NODE_S[id] = CUM[NODES[id].starts_at_centreline_vertex + 1] end
NODE_S.N6 = L - 1  -- finish: summit pad or s >= L - 1

--------------------------------------------------------------------------------
-- RACE STATE
--------------------------------------------------------------------------------
local race = {}
local squall = { t0 = nil, seed = 0, gust = 0, sc = 0, R = B.squall.R0 }
local SQ, GS, EN = B.squall, B.gust_shore, B.energy
local CAP_S = L / SQ.pace_studs_s + 60

local function now() return os.clock() end
local function r2(v) return math.floor(v * 100 + 0.5) / 100 end
local function clock() return squall.t0 and (now() - squall.t0) or 0 end
local function logEvent(player, ev, data)
    data = data or {}
    data.ev = ev; data.player = player.Name; data.t = r2(clock())
    print("RACE " .. HttpService:JSONEncode(data))
end
local function hrpOf(player) local c = player.Character; return c and c:FindFirstChild("HumanoidRootPart") or nil end
local function humOf(player) local c = player.Character; return c and c:FindFirstChild("Humanoid") or nil end
local function inBox(b, x, z) return x >= b.min[1] and x <= b.max[1] and z >= b.min[2] and z <= b.max[2] end

local function publish(player)
    local st = race[player]
    player:SetAttribute("BotModel", "wing_swarm")
    player:SetAttribute("RaceState", st.state)
    player:SetAttribute("CurrentNode", st.node or "")
    player:SetAttribute("RaceClock", r2(clock()))
    player:SetAttribute("NodeLog", HttpService:JSONEncode(st.log))
    player:SetAttribute("Energy", r2(st.E))
    player:SetAttribute("OutsideS", r2(st.outside))
    player:SetAttribute("Exits", st.exits)
    player:SetAttribute("Progress", r2(st.s))
    local cx, cz = pointAt(squall.sc)
    player:SetAttribute("SquallX", r2(cx)); player:SetAttribute("SquallZ", r2(cz)); player:SetAttribute("SquallR", r2(squall.R))
    player:SetAttribute("SquallS", r2(squall.sc)); player:SetAttribute("Gust", r2(squall.gust))
end
local function enterNode(player, id)
    local st = race[player]
    local t = r2(clock())
    if st.node then
        local e = st.log[#st.log]; e.exit = t; e.split = r2(t - e.enter)
        logEvent(player, "NODE_EXIT", { node = st.node, split = e.split })
    end
    st.node = id
    table.insert(st.log, { node = id, enter = t, mode = "walk" })
    logEvent(player, "NODE_ENTER", { node = id, parent = st.log[#st.log - 1] and st.log[#st.log - 1].node or nil })
end
local function stopBot(player, state, reason)
    local st, hum = race[player], humOf(player)
    st.state = state; st.reason = reason
    if hum then hum:CancelMoveTo(); hum.WalkSpeed = 0 end
    logEvent(player, string.upper(state), { node = st.node, reason = reason, s = r2(st.s), E = r2(st.E) })
end
local function newState()
    return { state = "pen", log = {}, node = nil, s = 0, E = EN.E0, outside = 0, exits = 0, wasOut = false, last = nil }
end

local function gaussian()
    local u1, u2 = math.max(1e-9, math.random()), math.random()
    return math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2)
end

--------------------------------------------------------------------------------
-- PLAYERS AND INPUT
--------------------------------------------------------------------------------
local function setupPlayer(player)
    race[player] = newState()
    local hrp, hum = hrpOf(player), humOf(player)
    if hum then hum.WalkSpeed = COURSE.bot_models[1].speed_studs_s or 5.5; hum.JumpPower = 50 end
    if hrp then hrp.Position = SPAWN + Vector3.new(0, 0, (#Players:GetPlayers() - 3) * 1.6) end
    player:SetAttribute("LastActionResult", "Ready")
    publish(player)
end
local function parsePosition(pos)
    if type(pos) ~= "table" then return nil end
    local x, y, z = tonumber(pos[1]), tonumber(pos[2]), tonumber(pos[3])
    if not x or not y or not z then return nil end
    return Vector3.new(x, y, z)
end

AgentInputService.InputReceived:Connect(function(player, inputType, data)
    local st, hum = race[player], humOf(player)
    if not st or not hum then return end
    data = data or {}
    if inputType == "Start" then
        if st.state ~= "pen" then return end
        if not squall.t0 then  -- the first Start releases the whole swarm's clock and the squall
            squall.t0 = now(); squall.seed = tonumber(data.seed) or 0
            math.randomseed(squall.seed); squall.gust = GS.ou_mean_studs_s
            print("RACE " .. HttpService:JSONEncode({ ev = "SQUALL_START", seed = squall.seed, pace = SQ.pace_studs_s, R0 = SQ.R0, R_min = SQ.R_min, gust_mu = GS.ou_mean_studs_s }))
        end
        st.state = "racing"; enterNode(player, "N0")
        player:SetAttribute("LastActionResult", "Started")
    elseif inputType == "MoveTo" then
        if st.state == "lost" or st.state == "downed" then return end
        local t = parsePosition(data.position)
        if not t then player:SetAttribute("LastActionResult", "MoveToFailed:InvalidPosition"); return end
        hum:MoveTo(t); player:SetAttribute("LastActionResult", "Moving")
    elseif inputType == "Stop" then
        hum:CancelMoveTo()
    elseif inputType == "Jump" then
        hum.Jump = true
    end
end)

RunService.Heartbeat:Connect(function(dt)
    if squall.t0 then
        local t = clock()
        squall.sc = math.min(L, SQ.pace_studs_s * t)
        squall.R = SQ.R0 + (SQ.R_min - SQ.R0) * squall.sc / L
        -- Ornstein-Uhlenbeck crosswind, clipped at 0
        squall.gust = math.max(0, squall.gust + GS.ou_reversion_per_s * (GS.ou_mean_studs_s - squall.gust) * dt + GS.ou_sigma * math.sqrt(dt) * gaussian())
        local cx, cz = pointAt(squall.sc)
        squallPart.Size = Vector3.new(2 * squall.R, 0.05, 2 * squall.R)
        squallPart.Position = Vector3.new(cx, 0.08, cz)
    end
    local cx, cz = pointAt(squall.sc)
    for _, player in ipairs(Players:GetPlayers()) do
        local st, hrp = race[player], hrpOf(player)
        if st and hrp then
            local p = hrp.Position
            if p.Y < -30 and st.state == "racing" then stopBot(player, "lost", "fell"); hrp.Anchored = true end
            if st.state == "racing" then
                -- gust shore: push toward the water
                if inBox(gb, p.X, p.Z) and squall.gust > 0 then
                    hrp.Position = p + Vector3.new(GS.direction[1] * squall.gust * dt, 0, GS.direction[2] * squall.gust * dt)
                    p = hrp.Position
                end
                -- energy: base + effort (speed from position change) + outside-the-squall drain
                local v = 0
                if st.last and dt > 0 then v = math.sqrt((p.X - st.last.X) ^ 2 + (p.Z - st.last.Z) ^ 2) / dt end
                st.last = p
                local out = (p.X - cx) ^ 2 + (p.Z - cz) ^ 2 > squall.R ^ 2
                st.E = st.E - (EN.base_drain_per_s + EN.effort_drain_per_s_per_speed2 * math.min(v, 8) ^ 2 + (out and SQ.outside_energy_drain_per_s or 0)) * dt
                if out then st.outside = st.outside + dt end
                if out and not st.wasOut then st.exits = st.exits + 1 end
                st.wasOut = out
                -- progress along the centreline and node entries
                st.s = math.max(st.s, project(p.X, p.Z, math.max(0, st.s - 6), st.s + 12))
                local nextIdx = 0
                for i, id in ipairs(ORDER) do if id == st.node then nextIdx = i + 1 end end
                if st.node == "N0" then nextIdx = 1 end
                local nid = ORDER[nextIdx]
                if nid and nid ~= "N6" and st.s >= NODE_S[nid] then enterNode(player, nid) end
                if st.node == "N5" and ((p.X - NODES.N6.zone.c[1]) ^ 2 + (p.Z - NODES.N6.zone.c[2]) ^ 2 <= NODES.N6.zone.r ^ 2 or st.s >= NODE_S.N6) then
                    enterNode(player, "N6"); local e = st.log[#st.log]; e.exit = e.enter; e.split = 0
                    st.state = "finished"; logEvent(player, "FINISH", { total = e.enter, E = r2(st.E) })
                elseif inBox(W.bay, p.X, p.Z) then stopBot(player, "lost", "water")
                elseif st.E <= EN.downed_at then stopBot(player, "downed", "energy")
                elseif clock() > CAP_S then stopBot(player, "timeout", "cap") end
            end
            publish(player)
        end
    end
end)

Players.PlayerAdded:Connect(setupPlayer)
Players.PlayerRemoving:Connect(function(player) race[player] = nil end)
for _, player in ipairs(Players:GetPlayers()) do setupPlayer(player) end

print("=== Mesa Island Race Course (" .. COURSE.id .. ") ===")
